"""Four initial H3 shots for the user-approved implied-horror BBQ."""
from pathlib import Path
import json,shutil,subprocess,sys,zipfile,hashlib
EP=Path(__file__).resolve().parent;ROOT=EP.parents[1];SK=ROOT/'.claude/skills/minimax-h3-video/scripts'
YAME=(ROOT/'02_CHARACTERS/references/yametaro-identity-prompt.md').read_text().split('```text\n')[1].split('```')[0].replace('[IMAGE REFERENCE]','Yametaro in <Picture 1>')
SOB='''Sobaya is the same broad muscular adult as the reference, short black hair, neutral gray exposed skin on neck, arms and hands, white rigid full-face mask with black circular eyeholes, long red markings, small black forehead dot. The opaque mask stays properly fitted at all times; its painted mouth stays unchanged, his voice comes from behind it. Reactions use his head and body. White fitted crewneck T-shirt, brown waist apron, black pants, white sneakers. His fitted white crew-neck T-shirt is a plain, undecorated garment. Its front is one uninterrupted opaque white cotton surface, with a subtle fabric grain, broad soft lighting gradients and natural fabric folds matching Picture 1. The shirt keeps this same material and appearance throughout all movement.'''
YUME='''Yumemin is exactly the cute smooth round blue tapir mascot shown in Picture 1: spherical blue front, white rear quarter, two small blue ears, simple black dot eyes, short flexible tapir nose, tiny rear tail, NO arms, hands, legs or wings. About 45cm diameter, freely hovering about 1.2m above ground. Preserve the same recognizable design and size, do not turn it into a realistic animal or human. No mallet or other objects.'''
GLOBAL='''Cinematic widescreen Japanese implied-horror comedy, 24fps. Picture 1 is the scene, identities, costumes and lighting reference. Natural live movement, not a still image. Preserve all characters as the same individuals. Only the dialogue explicitly quoted below, once each, natural conversational speed, no repetition, filler or extra words. No narrator or captions, no superimposed text. Ambient sound only, NO MUSIC. Horror is conveyed through stillness and editing. Never depict cooking, eating, cutting, injury, blood, remains or transformation of the blue mascot. Ordinary beef is the ONLY food at the BBQ; no chikuwa or purple food.'''
plan=[
 dict(id='ch01',frames=260,image='input_bbq_meat_v1.png',audio=['ch1_yotan.wav','ch1_sobaya.wav'],prompt='''Same evening backyard as Picture 1: Yotan seated left, same real Japanese face with blonde hair, tinted glasses, black leather jacket; Sobaya standing center; short stylized Yametaro right. Four ordinary beef pieces remain on charcoal grill, empty serving tray on table. At first the atmosphere is a casual home BBQ. Yotan looks at sparse meat then up at Sobaya and says once <d>[Japanese] あれ、肉足りなくない？</d>. Audio 1 is Yotan's exact line and voice. Sobaya answers calmly once from behind his rigid mask <d>[Japanese] ちょっと待っててください</d>. Audio 2 is Sobaya's exact line and voice. After finishing the sentence, Sobaya rests the tongs on the grill edge, then turns and walks away through the open backyard gate toward the dark wooded path. Follow him with a subtle camera pan as he recedes, keeping the others in foreground; finish with Sobaya passing into the dark path and disappearing beyond gate. Yotan and Yametaro stay at BBQ, silently watching. No other dialogue, no returning. Natural grill sizzle and footsteps.''' ,identities='sob+yame'),
 dict(id='ch02',frames=158,image='input_forest_alone_v1.png',audio=[],prompt='''A quiet suspense shot of the moonlit forest in Picture 1. ONLY Yumemin is present. It floats peacefully, gently bobbing a few centimeters, tiny nose movement, moving leaves and drifting mist. Camera slowly creeps toward the cute round mascot. Hold the stillness; no capture yet and no person enters this shot. The dark forest remains realistic, cute character design unchanged. Natural soft insects, leaves and faint distant footsteps near the end. Absolutely no human speech, words, cries or music.''',identities='yume'),
 dict(id='ch03',frames=192,image='input_forest_capture_v1.png',audio=[],prompt='''Begin at the exact wide composition in Picture 1: Sobaya at left beside tree, Yumemin hovering center-right two meters away. One continuous shot. Sobaya silently steps out from behind the tree and approaches to arm's reach. For a short beat he calmly looks at the floating mascot. Then he suddenly reaches out with both EMPTY bare gray hands and catches the round blue creature firmly around its sides. The hands make clear physical contact and stop its floating movement; hold it intact securely at chest height, preserving its spherical body and tiny nose. End immediately on this unmistakable capture pose with mascot still intact and visible. No running away, wrestling, escape, squeezing damage, biting, eating, tools, bag, weapons or cooking. No morphing or duplicate mascot. His white mask stays fitted, no dialogue or growls. Only footfalls on leaves and cloth rustle; forest insects briefly go quiet at capture. No impact violence or screams. Keep all body parts and the mascot within frame.''',identities='sob+yume'),
 dict(id='ch04',frames=243,image='input_bbq_notification_v1.png',audio=['ch4_yametaro.wav'],prompt='''Return to the exact backyard of Picture 1. Exactly TWO people: Yotan seated left, same real Japanese face blonde hair tinted glasses leather jacket; Yametaro short stylized purple-shirted character right holding one smartphone. Center position empty, dark gate/path visible behind. Sobaya remains absent for the entire shot, Yumemin is not here. After a brief quiet wait, a single clear smartphone notification CHIME sounds. Yametaro then looks down at the phone display facing himself (only back of phone faces camera), reads silently for a beat, and turns slightly toward Yotan. He announces cheerfully once <d>[Japanese] そば屋さんが肉みつけたって！</d>. Audio 1 is Yametaro's exact line and voice reference, natural Kansai-colored conversational delivery. Finish the full line and close mouth. Yotan says nothing; his smile fades subtly and he turns his head to look toward the dark empty gate. Camera holds the two people and ominously empty center, slowly drifting toward the gate for the last quiet beat. The four ordinary beef pieces already on grill keep sizzling. No arrival, no added meat, no mascot, no message text overlays, no reply or extra words. Notification then dialogue then only sizzle, no music.''',identities='yame')]

def main():
 job=EP/'generated/h3-horror-v1';job.mkdir(exist_ok=False);bundle=job/'bundle';bundle.mkdir()
 for i,c in enumerate(plan):
  identity='\n'.join(x for key,x in [('sob',SOB),('yame',YAME),('yume',YUME)] if key in c['identities'].split('+'))
  text=f'Duration {c["frames"]/24:.3f} seconds.\n\n'+GLOBAL+'\n\n'+identity+'\n\n'+c['prompt']+'\n'
  c['seed']=2026103101+i;c['prompt_file']=f'prompt_{c["id"]}_v1.txt'
  (EP/c['prompt_file']).write_text(text);(bundle/(c['id']+'.txt')).write_text(text)
  for asset in [c['image'],*c['audio']]:shutil.copy2(EP/asset,bundle/asset)
  args=[sys.executable,str(SK/'build_workflow.py'),'--mode','r2v','--profile','480p-turbo','--frames',str(c['frames']),'--seed',str(c['seed']),'--prefix','video/horror_'+c['id'],'--image',c['image'],'--prompt-file',str(bundle/(c['id']+'.txt')),'--out',str(bundle/(c['id']+'.json'))]
  for a in c['audio']:args+=['--audio',a]
  subprocess.run(args,check=True);shutil.copy2(bundle/(c['id']+'.json'),EP/(c['id']+'_workflow.json'))
 (EP/'chapter_plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2)+'\n');shutil.copy2(EP/'chapter_plan.json',bundle/'chapter_plan.json');shutil.copy2(EP/'colab_batch.py',bundle/'colab_remote.py')
 for name in ['setup_cuda.py','run_workflow.py']:shutil.copy2(SK/name,bundle/name)
 with zipfile.ZipFile(job/'inputs.zip','w',zipfile.ZIP_DEFLATED) as z:
  for f in sorted(bundle.iterdir()):z.write(f,f.name)
 (job/'job.json').write_text(json.dumps({'status':'prepared','bundle_sha256':hashlib.sha256((job/'inputs.zip').read_bytes()).hexdigest()},indent=2)+'\n')
 print('PREPARED',job)
if __name__=='__main__':main()
